  ('article-koc92nl5', 'feed-nvd', 'NIST CVE Feed', 'CVE-2026-3422 (CRITICAL)', 'https://www.twcert.org.tw/en/cp-139-10743-9a952-2.html', 'Cybersecurity', '2026-03-02T05:16:23.477Z'::timestamptz, '2026-03-08T15:11:45.441Z'::timestamptz, 'U-Office Force developed by e-Excellence has a Insecure Deserialization vulnerability, allowing unauthenticated remote attackers to execute arbitrary code on the server by sending maliciously crafted serialized content.', 'U-Office Force developed by e-Excellence has a Insecure Deserialization vulnerability, allowing unauthenticated remote attackers to execute arbitrary code on the server by sending maliciously crafted serialized content.'),
  ('article-hafym6kh', 'feed-nvd', 'NIST CVE Feed', 'CVE-2026-3413 (HIGH)', 'https://github.com/JXBbozaihuang/vuln-research/issues/1', 'Cybersecurity', '2026-03-02T05:16:23.240Z'::timestamptz, '2026-03-08T15:11:45.441Z'::timestamptz, 'A flaw has been found in itsourcecode University Management System 1.0. This vulnerability affects unknown code of the file /admin_single_student.php. This manipulation of the argument ID causes sql injection. The attack is possible to be carried out remotely. The exploit has been published and may be used.', 'A flaw has been found in itsourcecode University Management System 1.0. This vulnerability affects unknown code of the file /admin_single_student.php.'),
  ('article-oy6z6nam', 'feed-nvd', 'NIST CVE Feed', 'CVE-2026-2999 (CRITICAL)', 'https://www.changingtec.com/news_detail.jsp?item_id=348', 'Cybersecurity', '2026-03-02T05:16:22.743Z'::timestamptz, '2026-03-08T15:11:45.441Z'::timestamptz, 'IDExpert Windows Logon Agent developed by Changing has a Remote Code Execution vulnerability, allowing unauthenticated remote attackers to force the system to download arbitrary executable files from a remote source and execute them.', 'IDExpert Windows Logon Agent developed by Changing has a Remote Code Execution vulnerability, allowing unauthenticated remote attackers to force the system to download arbitrary executable files from a remote source and execute them.')
